{"diagnosis": "Fetch makes no progress (max_addr=0x00000000 with TRAP: no progress max_addr=0x00000000 and tohost FAIL 0xdead vs expected forward progress). mem_xfer stays 0 so mem_done at picorv32.v:376 never asserts. Root cause at picorv32.v:373 where mem_xfer is (mem_valid && mem_ready) && (mem_la_use_prefetched_high_word && mem_do_rinst) instead of ||, blocking both normal transfers and prefetched-high-word use defined at picorv32.v:372.", "patch_diff": "diff --git a/picorv32.v b/picorv32.v
--- a/picorv32.v
+++ b/picorv32.v
@@ -372,5 +372,5 @@
 	wire mem_la_use_prefetched_high_word = COMPRESSED_ISA && mem_la_firstword && prefetched_high_word && !clear_prefetched_high_word;
-	assign mem_xfer = (mem_valid && mem_ready) && (mem_la_use_prefetched_high_word && mem_do_rinst);
+	assign mem_xfer = (mem_valid && mem_ready) || (mem_la_use_prefetched_high_word && mem_do_rinst);

 	wire mem_busy = |{mem_do_prefetch, mem_do_rinst, mem_do_rdata, mem_do_wdata};
 	wire mem_done = resetn && ((mem_xfer && |mem_state && (mem_do_rinst || mem_do_rdata || mem_do_wdata)) || (&mem_state && mem_do_rinst)) &&", "expected": "tohost PASS (not FAIL 0xdead), no TRAP: no progress max_addr=0x00000000 with forward progress"}

